local SundialMaker = {}
local PRODUCTS = {
    garden_sundial = { name = "Vrtni sončnik", stoneCost = 3, metalCost = 1, time = 5, cost = 50, accuracy = 0.50, happiness = 2, description = "Preprost vrtni sončnik." },
    wall_sundial = { name = "Zidni sončnik", stoneCost = 2, paintCost = 1, time = 3, cost = 30, accuracy = 0.45, description = "Sončnik na zid." },
    portable_sundial = { name = "Prenosni sončnik", brassCost = 2, time = 7, cost = 100, accuracy = 0.65, prestige = 3, description = "Prenosni za potovanja." },
    equatorial_sundial = { name = "Ekvatorialni sončnik", brassCost = 3, stoneCost = 2, time = 14, cost = 300, accuracy = 0.80, prestige = 8, knowledge = 10, description = "Natančen ekvatorialni sončnik." },
    multiple_gnomon = { name = "Mnogognomon", brassCost = 4, stoneCost = 3, time = 20, cost = 500, accuracy = 0.85, prestige = 12, knowledge = 15, description = "Z več gnomoni za različne ure." },
    royal_sundial = { name = "Kraljevski sončnik", goldCost = 2, brassCost = 3, stoneCost = 5, time = 30, cost = 1000, accuracy = 0.95, prestige = 25, happiness = 8, knowledge = 25, description = "Veliki kraljevski sončnik z zlatom." },
}
local BUILDINGS = {
    workshop = { name = "Sončničarska delavnica", cost = { gold = 300, wood = 100, stone = 50 }, upkeep = 8, qualityBonus = 5 },
    stone_yard = { name = "Kamnito dvorišče", cost = { gold = 500, wood = 100, stone = 200 }, upkeep = 12, qualityBonus = 10 },
    gnomon_studio = { name = "Gnomonski atelje", cost = { gold = 1500, wood = 200, stone = 400, brass = 30 }, upkeep = 35, qualityBonus = 25 },
    royal_sundial_maker = { name = "Kraljevski sončničar", cost = { gold = 4000, wood = 400, stone = 800, brass = 50, gold = 30 }, upkeep = 80, qualityBonus = 40, prestigeBonus = 20 },
}
SundialMaker.stoneStock = 12; SundialMaker.metalStock = 5; SundialMaker.brassStock = 5; SundialMaker.paintStock = 3; SundialMaker.goldStock = 2
SundialMaker.productStock = {}; SundialMaker.buildings = {}; SundialMaker.maker = nil; SundialMaker.activeMaking = {}; SundialMaker.totalProducts = 0; SundialMaker.dayTimer = 0
function SundialMaker.init() SundialMaker.stoneStock=12; SundialMaker.metalStock=5; SundialMaker.brassStock=5; SundialMaker.paintStock=3; SundialMaker.goldStock=2; SundialMaker.productStock={}; SundialMaker.buildings={}; SundialMaker.maker=nil; SundialMaker.activeMaking={}; SundialMaker.totalProducts=0; SundialMaker.dayTimer=0; print("[SundialMaker] Royal Sundial & Gnomon Maker System initialized (6 products, 4 buildings)") end
function SundialMaker.hireMaker(n,s) s=s or math.random(40,85); local c=350+s*7; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SundialMaker.maker={name=n or ("Sončničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sončničar najet: %s (spretnost: %d)",SundialMaker.maker.name,s),"success") end; return true end
function SundialMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SundialMaker.build(id) local ok,e=SundialMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SundialMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SundialMaker.getQualityBonus() local b=0; for _,bd in ipairs(SundialMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SundialMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and SundialMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.metalCost and SundialMaker.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.brassCost and SundialMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.paintCost and SundialMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.goldCost and SundialMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #SundialMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SundialMaker.maker then return false,"Potreben sončničar" end; return true end
function SundialMaker.make(pt) local ok,e=SundialMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then SundialMaker.stoneStock=SundialMaker.stoneStock-d.stoneCost end; if d.metalCost then SundialMaker.metalStock=SundialMaker.metalStock-d.metalCost end; if d.brassCost then SundialMaker.brassStock=SundialMaker.brassStock-d.brassCost end; if d.paintCost then SundialMaker.paintStock=SundialMaker.paintStock-d.paintCost end; if d.goldCost then SundialMaker.goldStock=SundialMaker.goldStock-d.goldCost end; local t=d.time; if SundialMaker.maker then t=math.max(1,t-math.floor(SundialMaker.maker.skill/10)) end; table.insert(SundialMaker.activeMaking,{id="sundial_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,knowledge=d.knowledge or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function SundialMaker.completeMaking(m) local q=1.0+(SundialMaker.getQualityBonus()/100); if SundialMaker.maker then q=q+(SundialMaker.maker.skill/200) end; q=math.min(2.0,q); SundialMaker.productStock[m.productType]=(SundialMaker.productStock[m.productType] or 0)+1; SundialMaker.totalProducts=SundialMaker.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if SundialMaker.maker then SundialMaker.maker.itemsMade=SundialMaker.maker.itemsMade+1; if math.random()<0.15 then SundialMaker.maker.skill=math.min(100,SundialMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sončnik izdelan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function SundialMaker.update(dt) if not _G.state then return end; SundialMaker.dayTimer=SundialMaker.dayTimer+dt; if SundialMaker.dayTimer>=30 then SundialMaker.dayTimer=0; for i=#SundialMaker.activeMaking,1,-1 do local m=SundialMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SundialMaker.completeMaking(m); table.remove(SundialMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SundialMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SundialMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SundialMaker.getStats() return {stoneStock=SundialMaker.stoneStock,brassStock=SundialMaker.brassStock,goldStock=SundialMaker.goldStock,productStock=SundialMaker.productStock,numBuildings=#SundialMaker.buildings,hasMaker=SundialMaker.maker~=nil,makerName=SundialMaker.maker and SundialMaker.maker.name or "—",makerSkill=SundialMaker.maker and SundialMaker.maker.skill or 0,activeMaking=#SundialMaker.activeMaking,totalProducts=SundialMaker.totalProducts} end
return SundialMaker
